-- Launch content seed (PRD 6.1 - English at launch, Gujarati added progressively)
INSERT INTO page_text (id, page_key, block_key, content_en, content_gu) VALUES
('pt_about_title', 'about', 'title', 'About Gayatri Kamdhenu Sevatirth', NULL),
('pt_about_body', 'about', 'body', 'Gayatri Kamdhenu Sevatirth, Bhorda is affiliated with All World Gayatri Pariwar (AWGP.org), inspired by the vision of Pandit Shriram Sharma Acharya.

We welcome families, youth, and seekers to participate in seva, sadhana, yagya, education, and community upliftment at our campus in Bhorda, Gujarat.', NULL),
('pt_about_mission', 'about', 'mission', 'Our mission is to nurture seva, sadhana, and values-based living — strengthening character, compassion, and self-reliance in harmony with Gayatri Pariwar ideals.', NULL),
('pt_about_our_story_title', 'about-our-story', 'title', 'Our Story', NULL),
('pt_about_our_story_body', 'about-our-story', 'body', 'A visual journey through milestones of Gayatri Pariwar at Bhorda and beyond — from Amreshwar to the historic 108 Kundi Mahayagya.', NULL),
('pt_about_pandit_shriram_title', 'about-pandit-shriram', 'title', 'Pandit Shriram Sharma Acharya', NULL),
('pt_about_pandit_shriram_body', 'about-pandit-shriram', 'body', 'Founder of the Gayatri Pariwar movement, Pandit Shriram Sharma Acharya (1911–1990) dedicated his life to spiritual awakening, social reform, and the revival of yagya culture. His writings and guidance continue to inspire millions worldwide.', NULL),
('pt_about_mata_bhagwati_title', 'about-mata-bhagwati', 'title', 'Vandaniya Mata Bhagwati Devi Sharma', NULL),
('pt_about_mata_bhagwati_body', 'about-mata-bhagwati', 'body', 'Mata Bhagwati Devi Sharma embodied selfless seva alongside Gurudev. Her life of simplicity, courage, and devotion remains a guiding light for Gayatri Pariwar families.', NULL),
('pt_about_vedmata_gayatri_title', 'about-vedmata-gayatri', 'title', 'Vedmata Gayatri', NULL),
('pt_about_vedmata_gayatri_body', 'about-vedmata-gayatri', 'body', 'Gayatri is revered as Vedmata — the mother of the Vedas. Daily Gayatri japa and yagya sadhana form the spiritual foundation of our activities at Sevatirth Bhorda.', NULL),
('pt_about_awgp_title', 'about-awgp', 'title', 'All World Gayatri Pariwar', NULL),
('pt_about_awgp_body', 'about-awgp', 'body', 'AWGP is a global movement with millions of members, rooted in the vision of a balanced society through spirituality, education, and constructive programmes. Learn more at awgp.org.', NULL),
('pt_about_dr_chinmay_title', 'about-dr-chinmay', 'title', 'Present Mentor — Dr. Chinmay Pandya', NULL),
('pt_about_dr_chinmay_body', 'about-dr-chinmay', 'body', 'Dr. Chinmay Pandya serves as a guiding voice for Gayatri Pariwar today, carrying forward Gurudev''s mission through discourse, writing, and institutional leadership.', NULL),
('pt_about_mission_vision_title', 'about-mission-vision', 'title', 'Mission & Vision', NULL),
('pt_about_mission_vision_body', 'about-mission-vision', 'body', 'Mission: Integrate spirituality with practical living through seva, sadhana, and community programmes.

Vision: A self-reliant, values-based society where every family participates in yagya culture and constructive action.', NULL),
('pt_about_dabhoi_title', 'about-dabhoi', 'title', 'Gayatri Pariwar Dabhoi', NULL),
('pt_about_dabhoi_body', 'about-dabhoi', 'body', 'The Dabhoi centre has been a long-standing hub of Gayatri Pariwar activity in the region. Sevatirth Bhorda extends this legacy on the land generously donated for seva and sadhana.', NULL),
('pt_activity_yagya_title', 'activity-yagya', 'title', 'Yagya', NULL),
('pt_activity_yagya_body', 'activity-yagya', 'body', 'Daily and special yagyas are performed to purify the environment and consciousness. Families and volunteers are welcome to participate in havan and collective sadhana.', NULL),
('pt_activity_zhola_title', 'activity-zhola', 'title', 'Zhola Pustakalay', NULL),
('pt_activity_zhola_body', 'activity-zhola', 'body', 'A travelling library programme bringing spiritual and values-based literature to villages and schools.', NULL),
('pt_activity_trees_title', 'activity-trees', 'title', 'Tree Planting', NULL),
('pt_activity_trees_body', 'activity-trees', 'body', 'Environmental seva through tree plantation drives, organic awareness, and care for native species on campus.', NULL),
('pt_activity_sadhana_title', 'activity-sadhana', 'title', 'Sadhana', NULL),
('pt_activity_sadhana_body', 'activity-sadhana', 'body', 'Morning and evening group sadhana including Gayatri japa, meditation, and guided reflection.', NULL),
('pt_activity_daily_routine_title', 'activity-daily-routine', 'title', 'Daily Routine / Aarti', NULL),
('pt_activity_daily_routine_body', 'activity-daily-routine', 'body', 'The daily rhythm of temple aarti, meditation, and community prayer — see the schedule table below.', NULL),
('pt_activity_swadhyay_title', 'activity-swadhyay', 'title', 'Swadhyay', NULL),
('pt_activity_swadhyay_body', 'activity-swadhyay', 'body', 'Study circles on Gurudev''s literature, Vichar Kranti, and applied spirituality in daily life.', NULL),
('pt_activity_festivals_title', 'activity-festivals', 'title', 'Festival Celebrations', NULL),
('pt_activity_festivals_body', 'activity-festivals', 'body', 'Major festivals and parvas are celebrated with yagya, cultural programmes, and community meals.', NULL),
('pt_activity_farming_title', 'activity-farming', 'title', 'Organic Farming', NULL),
('pt_activity_farming_body', 'activity-farming', 'body', 'Organic cultivation on campus supports the gaushala and community kitchen with chemical-free produce.', NULL),
('pt_activity_medical_title', 'activity-medical', 'title', 'Vaccination & Medical Camps', NULL),
('pt_activity_medical_body', 'activity-medical', 'body', 'Periodic health camps and vaccination drives serve nearby villages in partnership with local volunteers.', NULL),
('pt_activity_bal_sanskar_title', 'activity-bal-sanskar', 'title', 'Bal Sanskar Shala', NULL),
('pt_activity_bal_sanskar_body', 'activity-bal-sanskar', 'body', 'Weekend values education for children through stories, games, mantra, and creative activities.', NULL),
('pt_activity_youth_title', 'activity-youth', 'title', 'Youth Cell', NULL),
('pt_activity_youth_body', 'activity-youth', 'body', 'Youth-led seva projects, leadership training, and engagement with AWGP programmes.', NULL),
('pt_activity_self_reliance_title', 'activity-self-reliance', 'title', 'Self-Reliance Training', NULL),
('pt_activity_self_reliance_body', 'activity-self-reliance', 'body', 'Skill-building workshops encouraging entrepreneurship and constructive livelihoods.', NULL),
('pt_activity_games_title', 'activity-games', 'title', 'Games / Annual Celebration', NULL),
('pt_activity_games_body', 'activity-games', 'body', 'Sports, games, and annual cultural celebrations bringing families together.', NULL),
('pt_sanskar_garbhadhan_title', 'sanskar-garbhadhan', 'title', 'Garbhadhan', NULL),
('pt_sanskar_garbhadhan_body', 'sanskar-garbhadhan', 'body', 'The Garbhadhan sanskar is performed according to Vedic tradition at Sevatirth Bhorda. Our priests and volunteers guide families through preparation, mantras, and the ceremony itself.', NULL),
('pt_sanskar_garbhadhan_timing', 'sanskar-garbhadhan', 'timing', 'Before conception — contact for guidance', NULL),
('pt_sanskar_punsavan_title', 'sanskar-punsavan', 'title', 'Punsavan', NULL),
('pt_sanskar_punsavan_body', 'sanskar-punsavan', 'body', 'The Punsavan sanskar is performed according to Vedic tradition at Sevatirth Bhorda. Our priests and volunteers guide families through preparation, mantras, and the ceremony itself.', NULL),
('pt_sanskar_punsavan_timing', 'sanskar-punsavan', 'timing', 'Third month of pregnancy', NULL),
