('pt_gaushala_title', 'gaushala', 'title', 'Gaushala', NULL),
('pt_gaushala_body', 'gaushala', 'body', 'Cow seva is central to our campus life. The gaushala provides care, fodder, and medical attention for cows while promoting organic farming and Gau Seva opportunities for devotees.', NULL),
