('pt_home_updates_teaser', 'home', 'updates_teaser', 'Explore spotlight events, the weekly schedule, and gallery highlights from campus life.', NULL),
('pt_home_connect_cta', 'home', 'connect_cta', 'Share your interest in seva, visits, donations, or volunteering — our team will respond personally.', NULL)
